import { useContext, useState } from 'react'
import { Link, useNavigate } from 'react-router-dom'
import AttendancenSApi from '../../ContextAPi/AttendanceSApi'
import AuthShell, { Field, SubmitButton, MailIcon, LockIcon, authStyles } from './AuthShell'

const Admin = () => {
  const context = useContext(AttendancenSApi)
  const { showAlert, bgcolor } = context
  const isDark = bgcolor === 'dark'
  const s = authStyles(isDark)

  const [credintial, setMycredintial] = useState({ email: '', password: '' })
  const [showPass, setShowPass] = useState(false)
  const [loading, setLoading] = useState(false)
  const navigate = useNavigate()

  const handleChange = (e) => {
    setMycredintial({ ...credintial, [e.target.name]: e.target.value })
  }

  const handleSubmit = async (e) => {
    e.preventDefault()
    setLoading(true)
    try {
      const response = await fetch('http://localhost:5000/api/user/adminlogin', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          email: credintial.email,
          password: credintial.password,
        }),
      })
      const json = await response.json()
      if (json.success) {
        localStorage.setItem('token', json.authtoken)
        showAlert('Login Successfully', 'success')
        navigate('/admindata')
      } else {
        showAlert('Invalid Credenital', 'danger')
      }
    } catch (err) {
      showAlert('Cannot reach the server. Try again.', 'danger')
    } finally {
      setLoading(false)
    }
  }

  const handleHelp = () => {
    showAlert(
      'Use the email and password you registered with. New here? Sign up first.',
      'info'
    )
  }

  return (
    <AuthShell
      isDark={isDark}
      title="Admin login"
      subtitle="Sign in to manage students and attendance."
      sideTitle="Welcome back"
      sideText="Log in to manage your students and their attendance."
      points={['Manage student records', 'Track attendance in one place']}
    >
      <form onSubmit={handleSubmit} className="mt-8">
        <div className="space-y-5">
          <Field
            isDark={isDark}
            id="email"
            label="Email"
            icon={<MailIcon />}
            type="email"
            value={credintial.email}
            onChange={handleChange}
            autoComplete="email"
            placeholder="you@example.com"
            required
          />
          <Field
            isDark={isDark}
            id="password"
            label="Password"
            icon={<LockIcon />}
            type={showPass ? 'text' : 'password'}
            value={credintial.password}
            onChange={handleChange}
            autoComplete="current-password"
            placeholder="Enter your password"
            required
            right={
              <button
                type="button"
                onClick={() => setShowPass((v) => !v)}
                className={`absolute inset-y-0 right-4 text-xs font-medium ${s.link}`}
              >
                {showPass ? 'Hide' : 'Show'}
              </button>
            }
          />
        </div>

        <SubmitButton
          loading={loading}
          disabled={loading || !credintial.email || !credintial.password}
        >
          Login
        </SubmitButton>

        <p className={`mt-5 text-center text-sm ${s.muted}`}>
          Don't have an account?{' '}
          <Link to="/adminsignup" className={`font-medium ${s.link}`}>
            Sign up
          </Link>
        </p>
        <button
          type="button"
          onClick={handleHelp}
          className={`mt-2 block w-full text-center text-sm font-medium ${s.link}`}
        >
          Need help signing in?
        </button>
      </form>
    </AuthShell>
  )
}

export default Admin
